// Generates src/knowledge.generated.ts from knowledge/{en,ar}/*.md (the bank-approved product FAQ
// that Ask AMIL searches) so it ships inside the bundle. The .md files are the source of truth; a
// test fails if the generated file is stale.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const entries = [];
for (const locale of ["en", "ar"]) {
  for (const f of readdirSync(join(root, "knowledge", locale))
    .filter((x) => x.endsWith(".md"))
    .sort()) {
    const raw = readFileSync(join(root, "knowledge", locale, f), "utf8");
    const m = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(raw);
    if (!m) throw new Error(`knowledge/${locale}/${f}: missing front matter`);
    const meta = Object.fromEntries(
      m[1].split("\n").map((line) => {
        const i = line.indexOf(":");
        return [line.slice(0, i).trim(), line.slice(i + 1).trim()];
      }),
    );
    entries.push({
      id: meta.id,
      locale,
      title: meta.title,
      keywords: meta.keywords
        .split(",")
        .map((k) => k.trim())
        .filter(Boolean),
      paragraphs: m[2]
        .trim()
        .split(/\n\s*\n/)
        .map((p) => p.trim()),
    });
  }
}
writeFileSync(
  join(root, "src", "knowledge.generated.ts"),
  `// GENERATED by scripts/gen-knowledge.mjs from knowledge/{en,ar}/*.md. Do not edit by hand.\nimport type { KnowledgeEntry } from "./knowledge";\n\nexport const KNOWLEDGE: KnowledgeEntry[] = ${JSON.stringify(entries, null, 2)};\n`,
);
